int main(){try{check(playableSpecies("Longstride")==HeroSpecies::Longstride,"actual fifth enum selection");CarrionPatch patch;patch.quantity=.8;Vec3 at{patch.x,2,patch.z};check(patch.sensed({patch.x+14,2,patch.z},2,.8)&&!patch.sensed({patch.x+14.01,2,patch.z},2,.8)&&!patch.sensed({patch.x,17,patch.z},2,.8)&&!patch.sensed(at,2,0)&&!patch.sensed(at,2,std::numeric_limits<double>::infinity()),"sense boundary/vertical/depleted/nonfinite");check(patch.eligible(at,2,true,true)&&!patch.eligible(at,2,false,true)&&!patch.eligible(at,2,true,false)&&!patch.eligible({patch.x+1.11,2,patch.z},2,true,true)&&!patch.eligible({patch.x,2.51,patch.z},2,true,true),"actual body support alive/reach/height");needs::NeedsCore needs(HeroSpecies::Longstride);needs.restoreState(.9,0,0,0,false);HeroSim hero;HeroDrinkAutonomy autonomy;auto action=autonomy.update(hero,needs,{patch.x-6,2,patch.z},1.57079632679,.1,false,at,true,false,needs::SuggestedActivity::Eat,211);check(action.forward&&hero.perception.attention()->source==211,"shared local carrion intention");action=autonomy.update(hero,needs,{patch.x-6,2,patch.z},0,.1,true,at,true,false,needs::SuggestedActivity::Eat,211);check(!action.forward&&!action.contact,"direct override");action=autonomy.update(hero,needs,{patch.x-36,2,patch.z},0,.1,false,std::nullopt,false,false,needs::SuggestedActivity::Eat,211);check(!action.active&&!hero.perception.attention(),"camera remote knowledge");
std::vector<HabitatSite> sites{{{0,0,0},false,true,{1}},{{4,0,0},true,false,{0}}};ResourceLedgerDto ledger{{{100,ResourceKind::Creek,10,2},{200,ResourceKind::Shrub,10,1},{211,ResourceKind::Shrub,.8,0}},{{90,100,2},{91,200,1}}};uint64_t next=100;engine::NativePopulationRegistry host(Population(42,1001,sites,8),ledger,{},{{0,100,sites[0].position},{1,200,sites[1].position}},next);auto original=host.snapshot();auto bindings=host.sessions();InteractionsCore interactions;interactions.beginSession(13);double dummy=.8;check(host.consume(13,211,.5)&&interactions.applyContact(13,211,true,.5,dummy),"first actual accepted contact");needs.feed(.5);check(std::abs(needs.hunger()-.4)<1e-12&&!host.consume(13,211,.5)&&!interactions.applyContact(13,211,true,.5,dummy),"exact relief held replay");interactions.beginSession(14);dummy=.3;check(host.consume(14,211,.3)&&interactions.applyContact(14,211,true,.3,dummy),"finite remainder fresh session");needs.feed(.3);auto after=host.ledger();check(std::abs(after.resources[2].consumedQuantity-.8)<1e-12&&patch.fraction(0)==0&&patch.fraction(.4)==.5&&std::abs(needs.hunger()-.1)<1e-12,"actual depletion/visible fraction/relief");check(after.resources[0].consumedQuantity==2&&after.resources[1].consumedQuantity==1&&host.sessions()==bindings&&host.actors().size()==8&&host.actors()[0].id==original.actors[0].id&&host.actors()[0].hunger==original.actors[0].hunger,"old resources/actors/bindings changed");check(after.sessions.size()==4&&after.sessions[2].sessionId==90&&after.sessions[2].amount==2&&after.sessions[3].sessionId==91&&after.sessions[3].amount==1,"old exact history missing/changed");auto finalActors=host.snapshot().actors;for(size_t i=0;i<original.actors.size();++i){const auto&a=original.actors[i];const auto&b=finalActors[i];check(a.id==b.id&&a.species==b.species&&a.position.x==b.position.x&&a.position.y==b.position.y&&a.position.z==b.position.z&&a.headingRadians==b.headingRadians&&a.distanceTravelledMeters==b.distanceTravelledMeters&&a.site==b.site&&a.target==b.target&&a.calendarAge==b.calendarAge&&a.stage==b.stage&&a.hunger==b.hunger&&a.thirst==b.thirst&&a.fatigue==b.fatigue&&a.injury==b.injury&&a.isResting==b.isResting&&a.activity==b.activity,"old NPC snapshot changed by hero carrion");}bool denied=false;try{host.consume(15,211,.1);}catch(const std::exception&){denied=true;}check(denied,"exhausted resource invented");Lifecycle life(HeroSpecies::Longstride);life.advance({1,2000});check(life.stage()==LifeStage::Juvenile&&life.species()==needs.species(),"Longstride profile");StalthosState world(42);world.setHero(1,1);world.heroDied();auto successor=beginNextLife(world,1,{},next);Lifecycle nextLife(playableSpecies("Longstride"));check(successor.hero==2&&nextLife.species()==HeroSpecies::Longstride&&host.ledger().sessions.size()==4,"selected succession components/reset resources");std::cout<<"LONG_REVIEW_OK actual_species_bodylocal_sense_support_shared_intention_direct_registry_exact_relief_replay_finite_remainder_history\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}

